  `Phase` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Progress` int NOT NULL DEFAULT '0',
  `PreviewStartSeconds` int NOT NULL DEFAULT '0',
  `ExpectedSpeakerCount` int DEFAULT NULL,
  `PreviewRelativePath` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `VoiceProfileRelativePath` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `VoiceProfileChecksum` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `SpeakerCount` int DEFAULT NULL,
  `VoiceSamples` json DEFAULT NULL,
  `RejectedVoiceReferences` json DEFAULT NULL,
  `FinalPlaylistPath` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `VoiceModel` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `DiarizationModel` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `SeparationModel` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `PipelineVersion` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `DisclosureVersion` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Watermarked` tinyint(1) NOT NULL DEFAULT '1',
