  `PreviewApprovedAt` datetime(3) DEFAULT NULL,
  `FinalApprovedByUserID` int DEFAULT NULL,
  `FinalApprovedAt` datetime(3) DEFAULT NULL,
  `CreatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `UpdatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `VoiceEngine` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'chatterbox',
  `VoiceModelRevision` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `GenerationConfigHash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `InputManifest` json DEFAULT NULL,
  `InputManifestHash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
