  KEY `AiDubbingJob_PreviewApprovedByUserID_fkey` (`PreviewApprovedByUserID`),
  KEY `AiDubbingJob_FinalApprovedByUserID_fkey` (`FinalApprovedByUserID`),
  KEY `idx_ai_dubbing_queue` (`Status`,`NextEligibleAt`,`CreatedAt`),
  KEY `idx_ai_dubbing_worker_status` (`AssignedWorkerID`,`Status`),
  KEY `idx_ai_dubbing_preferred_worker` (`PreferredWorkerID`,`LeaseExpiresAt`),
  KEY `idx_ai_dubbing_lease` (`LeaseExpiresAt`),
  CONSTRAINT `AiDubbingJob_AssignedWorkerID_fkey` FOREIGN KEY (`AssignedWorkerID`) REFERENCES `AiDubbingWorker` (`AiDubbingWorkerID`) ON DELETE SET NULL ON UPDATE CASCADE,
