INSERT INTO `AiDubbingJob` VALUES ('033f1a76-324f-46c9-bcc2-0f6f75fcad9e',13,'fr',NULL,1,'PUBLISHED','PUBLISHED',100,0,3,'uploads/video/13/audio/ai/fr/033f1a76-324f-46c9-bcc2-0f6f75fcad9e/preview/preview.wav','uploads/video/13/audio/ai/fr/033f1a76-324f-46c9-bcc2-0f6f75fcad9e/profile','9ec6c58cd7cffabf6398dd5dd959cc8cc07bce1b8d4f3aa62bed1c1f65a7b251',3,'[{\"text\": \"Faudrait un endroit tout vide pour faire les voitures, les deux poteaux et le scotch.\", \"speaker\": \"SPEAKER_00\", \"reviewedAt\": \"2026-09-10T17:31:42.571Z\", \"sourceStart\": 45.69, \"relativePath\": \"uploads/video/13/audio/ai/fr/033f1a76-324f-46c9-bcc2-0f6f75fcad9e/preview/voices/SPEAKER_00.wav\", \"reviewStatus\": \"ACCEPTED\", \"referenceSha256\": \"ab22be9b42544bd5b03a421ee665bc27f3c66c75ad5c735ffaefefdc076726ce\", \"reviewedByUserId\": 1, \"referenceSourceEnd\": 7.66, \"referenceSourceStart\": 2.98}, {\"text\": \"on est à 19 avec les vôtres. Donc, il reste ceux-là à mettre sur le capot et on est bon.\", \"speaker\": \"SPEAKER_01\", \"reviewedAt\": \"2026-09-10T17:31:49.839Z\", \"sourceStart\": 229.733, \"relativePath\": \"uploads/video/13/audio/ai/fr/033f1a76-324f-46c9-bcc2-0f6f75fcad9e/preview/voices/SPEAKER_01.wav\", \"reviewStatus\": \"ACCEPTED\", \"referenceSha256\": \"42bb9558d13142bf45b103683e83519aa8b7bdee1948c8863b56d03958ba14b9\", \"reviewedByUserId\": 1, \"referenceSourceEnd\": 24.14, \"referenceSourceStart\": 19.62}, {\"text\": \"Moi, je dirais directement à 25, parce que là, on est en train de dépenser du scotch pour rien. Ah ouais.\", \"speaker\": \"SPEAKER_02\", \"reviewedAt\": \"2026-09-10T17:31:57.036Z\", \"sourceStart\": 179.16, \"relativePath\": \"uploads/video/13/audio/ai/fr/033f1a76-324f-46c9-bcc2-0f6f75fcad9e/preview/voices/SPEAKER_02.wav\", \"reviewStatus\": \"ACCEPTED\", \"referenceSha256\": \"f0ea9280642b8b5396155d253409b61b98c5349d750d74811e949a330d37e030\", \"reviewedByUserId\": 1, \"referenceSourceEnd\": 42.53, \"referenceSourceStart\": 39.91}]',NULL,'uploads/video/