INSERT INTO `AiVideoTranscript` VALUES (6,'ja','[{\"end\": 34.37, \"text\": \"ドバス前に聞き取れなくていい\", \"start\": 32.79}, {\"end\": 39.18, \"text\": \"アークです\", \"start\": 34.37}, {\"end\": 44.39, \"text\": \"異世界にやってきて\", \"start\": 39.18}, {\"end\": 47.37, \"text\": \"目立たずひっそり冒険をするつもりでしたが\", \"start\": 44.39}, {\"end\": 48.71, \"text\": \"なんだそれ\", \"start\": 47.37}, {\"end\": 50.73, \"text\": \"呪いラリアット\", \"start\": 48.71}, {\"end\": 54.32, \"text\": \"せか、うまくいきません\", \"start\": 50.73}, {\"end\": 75.23, \"text\": \"ほう、アリアン殿、千代目殿、ポン太\", \"start\": 54.32}, {\"end\": 77.93, \"text\": \"鼓動よ、剣とその銀舞いよ\", \"start\": 75.23}, {\"end\": 85.84, \"text\": \"二人ともやるな\", \"start\": 77.93}, {\"end\": 87.5, \"text\": \"では、我も\", \"start\": 85.84}, {\"end\": 90.31, \"text\": \"雷属性ハイマップ\", \"start\": 87.5}, {\"end\": 92.94, \"text\": \"スタッフ\", \"start\": 90.82}, {\"end\": 174.44, \"text\": \"弾薬のダークエルフ\", \"start\": 92.94}, {\"end\": 178.45, \"text\": \"おねみにしみるなあ\", \"start\": 174.44}, {\"end\": 179.29, \"text\": \"ホンタよ\", \"start\": 178.45}, {\"end\": 180.07, \"text\": \"キュン\", \"start\": 179.29}, {\"end\": 227.85, \"text\": \"お前らの悪行もここまで\", \"start\": 180.07}, {\"end\": 252.91, \"text\": \"娘たちがお世話になりました\", \"start\": 227.85}, {\"end\": 256.07, \"text\": \"これは心ばかりのお礼です\", \"start\": 252.91}, {\"end\": 259.75, \"text\": \"さあさどうぞ遠慮なく召し上がってください\", \"start\": 256.07}, {\"end\": 262.15, \"text\": \"おおこれはすまないな\", \"start\": 259.75}, {\"end\": 263.93, \"text\": \"ではありがたく\", \"start\": 262.15}, {\"end\": 264.91, \"text\": \"ちょっとアーク\", \"start\": 263.93}, {\"end\": 266.45, \"text\": \"良いではないか\", \"start\": 264.91}, {\"end\": 268.53, \"text\": \"せっかくだ地層になろう\", \"start\": 266.45}, {\"end\": 275.6, \"text\": \"この宿場の名物鎧山蟹の唐揚げです\", \"start\": 268.53}, {\"end\": 277.65, \"text\": \"本当にいいの\", \"start\": 275.6}, {\"end\": 279.57, \"text\": \"みんなの前で食べちゃって\", \"start\": 277.65}, {\"end\": 281.1, \"text\": \"しやったー\", \"start\": 279.57}, {\"end\": 283.48, \"text\": \"高価な料理を目の前にしてつい\", \"start\": 281.1}, {\"end\": 286.84, \"text\": \"うちの宿場町にはお風呂もありますので\", \"start\": 283.48}, {\"end\": 289.02, \"text\": \"よかったら入っていってください\", \"start\": 286.84}, {\"end\": 292.4, \"text\": \"おおやはり温泉があるのだな\", \"start\": 289.02}, {\"end\": 296.68, \"text\": \"ええ町中の宿屋が共同で利用しているものですが\", \"start\": 292.4}, {\"end\": 300.48, \"text\": \"このあたりで風呂があるのはうちくらいなもんですよ\", \"start\": 296.68}, {\"end\": 301.84, \"text\": \"町の自慢です\", \"start\": 300.48}, {\"end\": 305.88, \"text\": \"そうかでは我は先に風呂をいただくとしよう\", \"start\": 302.12}, {\"end\": 308.52, \"text\": \"食事は部屋に運んでおいてくれ\", \"start\": 305.88}, {\"end\": 311.44, \"text\": \"騎士様、お背中をお流ししましょうか\", \"start\": 308.52}, {\"end\": 312.82, \"text\": \"いや、結構\", \"start\": 311.44}, {\"end\": 316.24, \"text\": \"我が上がるまで誰も風呂に近づかないように\", \"start\": 312.82}, {\"end\": 317.86, \"text\": \"絶対にだぞ\", \"start\": 316.24}, {\"end\": 320.21, \"text\": \"で、風呂はどこに?\", \"start\": 317.86}, {\"end\": 321.39, \"text\": \"ご案内します\", \"start\": 320.53}, {\"end\": 326.54, \"text\": \"騎士様、一体どうなされたのでしょう\", \"start\": 321.39}, {\"end\": 329.36, \"text\": \"騎士様は恥ずかしがり屋なの\", \"start\": 326.54}, {\"end\": 331.8, \"text\": \"はい、これも美味しいよ\", \"start\": 329.36}, {\"end\": 334.04, \"text\": \"はい、どうぞ\", \"start\": 331.8}, {\"end\": 335.61, \"text\": \"ありがとう\", \"start\": 334.04}, {\"end\": 338.39, \"text\": \"どんどん食べてくださいね\", \"start\": 335.61}, {\"end\": 344.92, \"text\": \"あの私たちのこと何とも思わないんですか\", \"start\": 338.39}, {\"end\": 345.28, \"text\": \"ええ\", \"start\": 344.92}, {\"end\": 350.54, \"text\": \"この辺はエルフも獣人も滅多に見ませんのでね\", \"start\": 345.28}, {\"end\": 353.24, \"text\": \"珍しくは思いますが\", \"start\": 350.54}, {\"end\": 357.98, \"text\": \"ああ思ってたより私たちと変わらないのね\", \"start\": 353.24}, {\"end\": 361.88, \"text\": \"人間もいろいろなのですね\", \"start\": 357.98}, {\"end\": 374.21, \"text\": \"うっ うっ うっ うっ うっ うっ うっ\", \"start\": 369.01}, {\"end\": 374.31, \"text\": \"うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ う\", \"start\": 374.21}, {\"end\": 384.91, \"text\": \"骨身にしみるなポン太よ\", \"start\": 374.21}, {\"end\": 388.75, \"text\": \"アークまだ入ってるみたいね\", \"start\": 384.91}, {\"end\": 390.65, \"text\": \"お風呂が好きなんですね\", \"start\": 388.75}, {\"end\": 393.19, \"text\": \"アリアン殿たちも来たようだな\", \"start\": 390.65}, {\"end\": 395.41, \"text\": \"おいアリアン殿\", \"start\": 393.19}, {\"end\": 398.27, \"text\": \"何よ大きな声出して\", \"start\": 395.41}, {\"end\": 414.54, \"text\": \"男言うと女言うを間違えるなんて\", \"start\": 398.27}, {\"end\": 415.64, \"text\": \"まったくです\", \"start\": 414.54}, {\"end\": 423.58, \"text\": \"だいたいアーク呪いを解く泉に行って人間の姿に戻るんでしょ\", \"start\": 415.64}, {\"end\": 425.98, \"text\": \"こんなにのんびりしてていいの\", \"start\": 423.58}, {\"end\": 431.08, \"text\": \"泉がある風流山脈とは反対方向に来てしまいましたね\", \"start\": 426.82}, {\"end\": 433.98, \"text\": \"アークがあっちこっち寄り道しちゃうから\", \"start\": 431.08}, {\"end\": 436.12, \"text\": \"仕方がないではないか\", \"start\": 433.98}, {\"end\": 438.9, \"text\": \"困っているものを放ってはおけるだろう\", \"start\": 436.12}, {\"end\": 442.38, \"text\": \"おばあさんを故郷の町まで送り届けたり\", \"start\": 438.9}, {\"end\": 446.84, \"text\": \"宝石を盗んだ窃盗団を壊滅させたり\", \"start\": 442.38}, {\"end\": 450.16, \"text\": \"都会にさらわれた子供を助けに行ったり\", \"start\": 446.84}, {\"end\": 453.2, \"text\": \"いつの間にやらこんなところまで\", \"start\": 450.16}, {\"end\": 457.7, \"text\": \"そこがアーク殿のいいところではありますが\", \"start\": 454.44}, {\"end\": 461.48, \"text\": \"千嫁ちゃんもごめんね付き合わせちゃって\", \"start\": 457.7}, {\"end\": 467.56, \"text\": \"そうそう泉の近くには人心一族の失われし場所があるかもしれんのだったな\", \"start\": 461.48}, {\"end\": 474.08, \"text\": \"はい人心一族の祖初代半蔵様が住んでいたと言われる伝説の場所です\", \"start\": 467.56}, {\"end\": 477.8, \"text\": \"その探索も千代目ちゃんの任務なんだからね\", \"start\": 474.08}, {\"end\": 482.16, \"text\": \"寄り道ばっかりしてたら千代目ちゃんに迷惑よ\", \"start\": 477.8}, {\"end\": 485.3, \"text\": \"そうであったすまんすまん\", \"start\": 482.16}, {\"end\": 489.4, \"text\": \"それは相当アリアン殿長くて綺麗な足ですね\", \"start\": 485.3}, {\"end\": 492.2, \"text\": \"お肌もスベスベで\", \"start\": 490.4}, {\"end\": 495.1, \"text\": \"ちょっと吉山ちゃんどこ触ってんの\", \"start\": 492.2}, {\"end\": 497.42, \"text\": \"おかしい\", \"start\": 495.1}, {\"end\": 503, \"text\": \"ではここからは寄り道せずに行くとするか\", \"start\": 497.42}, {\"end\": 505.28, \"text\": \"なポンタよ\", \"start\": 503}, {\"end\": 517.41, \"text\": \"キューン\", \"start\": 505.28}, {\"end\": 521.67, \"text\": \"ああそうしたら畑に水を引くのにも困らねえだろ\", \"start\": 517.41}, {\"end\": 538.65, \"text\": \"どうしたんでしょうか\", \"start\": 521.67}, {\"end\": 542.41, \"text\": \"なんかこの村に入ってからずっと様子が変やね\", \"start\": 538.65}, {\"end\": 547.05, \"text\": \"うん なんだかみんな我らを避けているような\", \"start\": 542.41}, {\"end\": 559.26, \"text\": \"どうした 大丈夫か少年\", \"start\": 547.05}, {\"end\": 565.54, \"text\": \"一体どういうことなのかしら\", \"start\": 559.26}, {\"end\": 568.97, \"text\": \"ああ 血が出ているではないか\", \"start\": 565.54}, {\"end\": 571.41, \"text\": \"どれ 火\", \"start\": 568.97}, {\"end\": 575.28, \"text\": \"これでいいだろう\", \"start\": 571.41}, {\"end\": 582.77, \"text\": \"なあに 礼には及ばん\", \"start\": 575.28}, {\"end\": 588.75, \"text\": \"あの あなたたちは白銀の暗黒騎士と残虐のダークエルフではないのですか\", \"start\": 582.77}, {\"end\": 591.47, \"text\": \"白銀の暗黒騎士と\", \"start\": 588.75}, {\"end\": 593.37, \"text\": \"残虐のダークエルフ\", \"start\": 591.47}, {\"end\": 599.62, \"text\": \"何なのよこれ\", \"start\": 593.37}, {\"end\": 604.44, \"text\": \"この騎士とエルフが最近ここらで大勢人をさらっているんです\", \"start\": 599.62}, {\"end\": 608.52, \"text\": \"アーク殿とアリアン殿の偽物でしょうか\", \"start\": 604.44}, {\"end\": 610.84, \"text\": \"偽物とは\", \"start\": 608.52}, {\"end\": 613.36, \"text\": \"目立たぬようにしていたつもりだが\", \"start\": 610.84}, {\"end\": 616.84, \"text\": \"我も随分と有名人になってしまったようだな\", \"start\": 613.36}, {\"end\": 618.9, \"text\": \"軟気なこと言ってる場合じゃないでしょう\", \"start\": 616.84}, {\"end\": 621.68, \"text\": \"私の偽物だなんて許せない\", \"start\": 618.9}, {\"end\": 625.84, \"text\": \"まっすぐ泉に行こうと思ったがそうも行かなくなったようだな\", \"start\": 621.68}, {\"end\": 627.12, \"text\": \"ポンタよ\", \"start\": 625.84}, {\"end\": 635.52, \"text\": \"でこいつらはどこに現れるの\", \"start\": 627.12}, {\"end\": 648.59, \"text\": \"ユリアーナ姫のおかげでみんな解放されてよかったわねアリアンさん\", \"start\": 635.52}, {\"end\": 653.53, \"text\": \"怖い顔をしていては相手を警戒させてしまいます\", \"start\": 648.59}, {\"end\": 655.65, \"text\": \"自然にしていないと\", \"start\": 653.53}, {\"end\": 657.61, \"text\": \"そうね\", \"start\": 655.65}, {\"end\": 662.59, \"text\": \"ほんとねローデン王国のユリアーノ姫が\", \"start\": 657.61}, {\"end\": 666.05, \"text\": \"エルフの救出と保護を決めてくださったおかげで\", \"start\": 662.59}, {\"end\": 670.11, \"text\": \"捕まっていた私たちもやっと自由の身になれたのよね\", \"start\": 666.05}, {\"end\": 673.53, \"text\": \"セリフが説明的で長くて棒読みです\", \"start\": 670.11}, {\"end\": 678.23, \"text\": \"仕方ないじゃないそんなお芝居なんてしたこと\", \"start\": 673.53}, {\"end\": 680.57, \"text\": \"気づかないふりをして\", \"start\": 678.23}, {\"end\": 684.44, \"text\": \"どさくさに紛れて私たち獣人も逃げ出せたし\", \"start\": 680.95}, {\"end\": 687.96, \"text\": \"でもここからだと私の里は遠いのよね\", \"start\": 684.44}, {\"end\": 691.52, \"text\": \"一体どうやって帰ればいいのか\", \"start\": 687.96}, {\"end\": 702.75, \"text\": \"千代目ちゃんやっつけるんじゃないの\", \"start\": 691.52}, {\"end\": 704.87, \"text\": \"他にも捕まった人たちがいます\", \"start\": 702.75}, {\"end\": 707.19, \"text\": \"アジトへ連れて行ってもらいましょう\", \"start\": 704.87}, {\"end\": 709.65, \"text\": \"助けて助けて\", \"start\": 707.19}, {\"end\": 724.23, \"text\": \"こうやるじゃない本物ほどじゃないけど\", \"start\": 709.65}, {\"end\": 727.16, \"text\": \"助けてください\", \"start\": 724.23}, {\"end\": 730.04, \"text\": \"命だけは命だけは\", \"start\": 727.16}, {\"end\": 733.06, \"text\": \"千代目ちゃん本当にお芝居上手ね\", \"start\": 730.04}, {\"end\": 734.56, \"text\": \"忍びですから\", \"start\": 733.06}, {\"end\": 736.66, \"text\": \"ほらアリアン殿も\", \"start\": 734.56}, {\"end\": 738.14, \"text\": \"許して\", \"start\": 736.66}, {\"end\": 740.26, \"text\": \"殺さないで\", \"start\": 738.14}, {\"end\": 745.02, \"text\": \"エルフと獣神か\", \"start\": 740.26}, {\"end\": 746.94, \"text\": \"女物が来たぜ\", \"start\": 745.02}, {\"end\": 749.62, \"text\": \"なんだ二人だけかよ\", \"start\": 746.94}, {\"end\": 751.88, \"text\": \"この辺でだいぶ暴れたからな\", \"start\": 749.62}, {\"end\": 753.44, \"text\": \"用心して\", \"start\": 751.88}, {\"end\": 755.94, \"text\": \"近づく奴らも減っちまったみたいだな\", \"start\": 753.44}, {\"end\": 756.92, \"text\": \"行こうぜ\", \"start\": 755.94}, {\"end\": 760.91, \"text\": \"ボスが待ってる\", \"start\": 756.92}, {\"end\": 771.41, \"text\": \"見ろよこのエルフの胸\", \"start\": 760.91}, {\"end\": 773.37, \"text\": \"たまんねえな\", \"start\": 771.41}, {\"end\": 777.67, \"text\": \"やらしい服着やがってよ誘ってんのか\", \"start\": 773.37}, {\"end\": 779.47, \"text\": \"我慢です\", \"start\": 777.67}, {\"end\": 784.65, \"text\": \"たまんねえメスの匂い\", \"start\": 779.47}, {\"end\": 788.15, \"text\": \"売りもんに手出すとボスにどやされるぞ\", \"start\": 784.65}, {\"end\": 789.39, \"text\": \"我慢です\", \"start\": 788.15}, {\"end\": 794.29, \"text\": \"こいつ入れてって群れんだよな\", \"start\": 789.39}, {\"end\": 799.62, \"text\": \"おいおい顔見せんなっつーの\", \"start\": 794.29}, {\"end\": 802.22, \"text\": \"足だけならいい女なんだけどな\", \"start\": 799.62}, {\"end\": 806.96, \"text\": \"ねっ俺すぬ気も吐いてねーんだぜ アジア\", \"start\": 802.22}, {\"end\": 810.28, \"text\": \"のより綺麗かもなぁ\", \"start\": 806.96}, {\"end\": 841.51, \"text\": \"いやなぁ 本当にセクトに会いに行くのですか\", \"start\": 811.62}, {\"end\": 847.24, \"text\": \"はいセリアなお姉さま 大丈夫かしら危険ではないの\", \"start\": 841.51}, {\"end\": 853.23, \"text\": \"私はエルフの大長老 ファンガス様という後ろ盾を持ちました\", \"start\": 847.24}, {\"end\": 855.83, \"text\": \"お兄様も簡単に手出しはできないはず\", \"start\": 853.23}, {\"end\": 863.74, \"text\": \"こちらから探りを入れに参ります\", \"start\": 855.83}, {\"end\": 868.63, \"text\": \"くそぼれ\", \"start\": 863.74}, {\"end\": 872.37, \"text\": \"そいつらが今日の獲物か\", \"start\": 868.63}, {\"end\": 876.13, \"text\": \"そろそろ使いが来る頃だ\", \"start\": 872.37}, {\"end\": 879.29, \"text\": \"こんだけ売り物が揃ってりゃ十分だな\", \"start\": 876.13}, {\"end\": 881.81, \"text\": \"今日の獲物は極上ですよ\", \"start\": 879.29}, {\"end\": 883.49, \"text\": \"獣人とエルフです\", \"start\": 881.81}, {\"end\": 887.81, \"text\": \"獣人とエルフか\", \"start\": 883.49}, {\"end\": 911.04, \"text\": \"白銀の騎士と女エルフ\", \"start\": 887.81}, {\"end\": 913.52, \"text\": \"まさか、本物か、アリアン殿\", \"start\": 911.04}, {\"end\": 914.96, \"text\": \"遅い\", \"start\": 913.52}, {\"end\": 921.03, \"text\": \"さてと、ひとさらいのアジトに乗り込むことには成功であるな\", \"start\": 914.96}, {\"end\": 926.84, \"text\": \"もしや、我の偽物というのはあやつか?\", \"start\": 921.03}, {\"end\": 929.56, \"text\": \"本多よ、あれは我に似てるか?\", \"start\": 927.38}, {\"end\": 934.23, \"text\": \"そういえば、アリアン殿の偽物はいずこに?\", \"start\": 931.31}, {\"end\": 935.47, \"text\": \"聞かないで!\", \"start\": 934.51}, {\"end\": 939.03, \"text\": \"何をしてる!やれ!やれ!\", \"start\": 936.73}, {\"end\": 942.95, \"text\": \"しおめ殿、アリアン殿\", \"start\": 941.35}, {\"end\": 943.69, \"text\": \"はい\", \"start\": 942.95}, {\"end\": 945.67, \"text\": \"じり成敗してやりましょう\", \"start\": 943.69}, {\"end\": 953.17, \"text\": \"この馬\", \"start\": 945.67}, {\"end\": 957.23, \"text\": \"ったいねえな\", \"start\": 953.17}, {\"end\": 958.77, \"text\": \"おとなしくしてりゃ\", \"start\": 957.23}, {\"end\": 960.65, \"text\": \"俺が可愛がってやったもん\", \"start\": 958.77}, {\"end\": 964.2, \"text\": \"なは\", \"start\": 960.65}, {\"end\": 965.62, \"text\": \"この世\", \"start\": 964.2}, {\"end\": 967.02, \"text\": \"剣に纏いて\", \"start\": 965.62}, {\"end\": 968.24, \"text\": \"貫き果てろ\", \"start\": 967.02}, {\"end\": 975.62, \"text\": \"誰の足が本物より綺麗ですって\", \"start\": 968.24}, {\"end\": 1053.1, \"text\": \"ううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううううう\", \"start\": 975.62}, {\"end\": 1055.44, \"text\": \"どやの\", \"start\": 1053.1}, {\"end\": 1065.56, \"text\": \"昔の俺と同じだと思うなよ お前たちを倒すためにわざとここに誘い込んだんだ\", \"start\": 1058.76}, {\"end\": 1068.85, \"text\": \"んですって きゅうっ\", \"start\": 1065.56}, {\"end\": 1068.95, \"text\": \"いいいいいいいいいいいい いいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいいい\", \"start\": 1068.85}, {\"end\": 1069.95, \"text\": \"どうしたポンタ\", \"start\": 1068.85}, {\"end\": 1073.99, \"text\": \"犬よ魔性軍団\", \"start\": 1069.95}, {\"end\": 1082.66, \"text\": \"まさかあれは\", \"start\": 1073.99}, {\"end\": 1083.91, \"text\": \"ゴブリン\", \"start\": 1082.66}, {\"end\": 1087.31, \"text\": \"やはりゴブリン\", \"start\": 1083.91}, {\"end\": 1091.31, \"text\": \"しかもゴブリンロードまで\", \"start\": 1087.31}, {\"end\": 1094.32, \"text\": \"ポンタジー来た\", \"start\": 1091.31}, {\"end\": 1098.51, \"text\": \"ゴブリン森や洞窟で集団で生活し\", \"start\": 1094.32}, {\"end\": 1103.11, \"text\": \"繁殖力が強く人間の女性をさらって子供を産ませたりもする\", \"start\": 1098.51}, {\"end\": 1106.31, \"text\": \"一体一体はそう強くもないが凶暴で\", \"start\": 1103.11}, {\"end\": 1109.21, \"text\": \"群れで攻撃してくると厄介な奴\", \"start\": 1106.31}, {\"end\": 1112.91, \"text\": \"そういうことはよく知ってるのよね\", \"start\": 1109.21}, {\"end\": 1115.89, \"text\": \"パパの無念今こそ晴らしてやる\", \"start\": 1112.91}, {\"end\": 1119.09, \"text\": \"行っていけあの二人を殺す\", \"start\": 1115.89}, {\"end\": 1122.73, \"text\": \"喜んでる場合ではないんだ\", \"start\": 1119.09}, {\"end\": 1132.37, \"text\": \"どんな息子がどうしてゴブリンをあえてるのよ\", \"start\": 1122.73}, {\"end\": 1136.21, \"text\": \"言ったろ昔の俺と思うなと\", \"start\": 1132.37}, {\"end\": 1138.95, \"text\": \"俺は力を手に入れたのだ\", \"start\": 1136.21}, {\"end\": 1155.32, \"text\": \"キリがない\", \"start\": 1138.95}, {\"end\": 1163.68, \"text\": \"こいつが群れの王様だ\", \"start\": 1155.32}, {\"end\": 1170.46, \"text\": \"では行くぞ\", \"start\": 1163.68}, {\"end\": 1172.02, \"text\": \"中級範囲魔法\", \"start\": 1170.46}, {\"end\": 1173.99, \"text\": \"クファンゲ\", \"start\": 1172.02}, {\"end\": 1176.8, \"text\": \"ちょ、ちょっと\", \"start\": 1173.99}, {\"end\": 1179.56, \"text\": \"こんなところで地形魔法なんか使ったら\", \"start\": 1176.8}, {\"end\": 1207.32, \"text\": \"助かった\", \"start\": 1179.56}, {\"end\": 1210.45, \"text\": \"あ、これにて\", \"start\": 1207.32}, {\"end\": 1223.7, \"text\": \"ほら、進め\", \"start\": 1210.45}, {\"end\": 1227.85, \"text\": \"奴らの話だと\", \"start\": 1223.7}, {\"end\": 1230.19, \"text\": \"人間もエルフも獣人も\", \"start\": 1227.85}, {\"end\": 1234.45, \"text\": \"他より高い値で取引してくれる国外の商人がいるって\", \"start\": 1230.19}, {\"end\": 1237.8, \"text\": \"国外とはどこの国なのですか\", \"start\": 1234.45}, {\"end\": 1239.92, \"text\": \"あやつも知らぬそうだ\", \"start\": 1237.8}, {\"end\": 1243.87, \"text\": \"でもなぜゴブリンを操れたのでしょう\", \"start\": 1239.92}, {\"end\": 1246.09, \"text\": \"魔獣を従えるなんて\", \"start\": 1243.87}, {\"end\": 1248.11, \"text\": \"並のものにできることではありません\", \"start\": 1246.09}, {\"end\": 1250.07, \"text\": \"あのゴブリンたちも\", \"start\": 1248.11}, {\"end\": 1253.58, \"text\": \"その国外の商人が貸してくれたそうよ\", \"start\": 1250.07}, {\"end\": 1256.52, \"text\": \"ドラムスコが術を身につけたわけじゃなくって\", \"start\": 1253.58}, {\"end\": 1259.38, \"text\": \"初めから言うことを聞いたんですって\", \"start\": 1256.52}, {\"end\": 1266.41, \"text\": \"そういえば宿場町の娘たちを襲っていた男も多くを操っていた\", \"start\": 1259.38}, {\"end\": 1270.15, \"text\": \"何か関係があるのかもしれんな\", \"start\": 1266.41}, {\"end\": 1283.66, \"text\": \"さあ行きなさい\", \"start\": 1270.15}, {\"end\": 1287.57, \"text\": \"働くのです旅のために\", \"start\": 1283.66}, {\"end\": 1299.72, \"text\": \"僕は一度里に戻って他に情報がないか調べてきます\", \"start\": 1287.57}, {\"end\": 1301.84, \"text\": \"お願いね千代目ちゃん\", \"start\": 1299.72}, {\"end\": 1306.58, \"text\": \"さてまた寄り道をしてしまったが\", \"start\": 1303.24}, {\"end\": 1309.84, \"text\": \"我らは本来の目的の風流山脈にある\", \"start\": 1306.58}, {\"end\": 1312.34, \"text\": \"呪いを解く泉に向かうとするか\", \"start\": 1309.84}, {\"end\": 1316.16, \"text\": \"ねえアーク\", \"start\": 1312.34}, {\"end\": 1320.19, \"text\": \"ここまで来たんだし\", \"start\": 1316.16}, {\"end\": 1323.93, \"text\": \"ちょっとだけ寄って行きたいところがあるんだけど\", \"start\": 1320.19}, {\"end\": 1327.2, \"text\": \"寄って行きたいところ?\", \"start\": 1323.93}, {\"end\": 1328.33, \"text\": \"キャー\", \"start\": 1327.83}, {\"end\": 1341.19, \"text\": \"よくなりたかったんだ\", \"start\": 1328.33}, {\"end\": 1345.07, \"text\": \"約束 記憶 風に纏う\", \"start\": 1341.19}, {\"end\": 1348.89, \"text\": \"大丈夫もう一人じゃないからね\", \"start\": 1345.07}, {\"end\": 1351.73, \"text\": \"雨は頬をかすった\", \"start\": 1348.89}, {\"end\": 1354.91, \"text\": \"今日が明日になる一瞬の高い目\", \"start\": 1351.73}, {\"end\": 1357.85, \"text\": \"弱さが強さになるアルゴリズムとは違う力学\", \"start\": 1354.91}, {\"end\": 1358.81, \"text\": \"証明できるか\", \"start\": 1357.85}, {\"end\": 1360.93, \"text\": \"あなたに届けと願う\", \"start\": 1358.81}, {\"end\": 1361.61, \"text\": \"大勢では\", \"start\": 1360.93}]','ドバス前に聞き取れなくていい\nアークです\n異世界にやってきて\n目立たずひっそり冒険をするつもりでしたが\nなんだそれ\n呪いラリアット\nせか、うまくいきません\nほう、アリアン殿、千代目殿、ポン太\n鼓動よ、剣とその銀舞いよ\n二人ともやるな\nでは、我も\n雷属性ハイマップ\nスタッフ\n弾薬のダークエルフ\nおねみにしみるなあ\nホンタよ\nキュン\nお前らの悪行もここまで\n娘たちがお世話になりました\nこれは心ばかりのお礼です\nさあさどうぞ遠慮なく召し上がってください\nおおこれはすまないな\nではありがたく\nちょっとアーク\n良いではないか\nせっかくだ地層になろう\nこの宿場の名物鎧山蟹の唐揚げです\n本当にいいの\nみんなの前で食べちゃって\nしやったー\n高価な料理を目の前にしてつい\nうちの宿場町にはお風呂もありますので\nよかったら入っていってください\nおおやはり温泉があるのだな\nええ町中の宿屋が共同で利用しているものですが\nこのあたりで風呂があるのはうちくらいなもんですよ\n町の自慢です\nそうかでは我は先に風呂をいただくとしよう\n食事は部屋に運んでおいてくれ\n騎士様、お背中をお流ししましょうか\nいや、結構\n我が上がるまで誰も風呂に近づかないように\n絶対にだぞ\nで、風呂はどこに?\nご案内します\n騎士様、一体どうなされたのでしょう\n騎士様は恥ずかしがり屋なの\nはい、これも美味しいよ\nはい、どうぞ\nありがとう\nどんどん食べてくださいね\nあの私たちのこと何とも思わないんですか\nええ\nこの辺はエルフも獣人も滅多に見ませんのでね\n珍しくは思いますが\nああ思ってたより私たちと変わらないのね\n人間もいろいろなのですね\nうっ うっ うっ うっ うっ うっ うっ\nうっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ うっ う\n骨身にしみるなポン太よ\nアークまだ入ってるみたいね\nお風呂が好きなんですね\nアリアン殿たちも来たようだな\nおいアリアン殿\n何よ大きな声出して\n男言うと女言うを間違えるなんて\nまったくです\nだいたいアーク呪いを解く泉に行って人間の姿に戻るんでしょ\nこんなにのんびりしてていいの\n泉がある風流山脈とは反対方向に来てしまいましたね\nアークがあっちこっち寄り道しちゃうから\n仕方がないではないか\n困っているものを放ってはおけるだろう\nおばあさんを故郷の町まで送り届けたり\n宝石を盗んだ窃盗団を壊滅させたり\n都会にさらわれた子供を助けに行ったり\nいつの間にやらこんなところまで\nそこがアーク殿のいいところではありますが\n千嫁ちゃんもごめんね付き合わせちゃって\nそうそう泉の近くには人心一族の失われし場所があるかもしれんのだったな\nはい人心一族の祖初代半蔵様が住んでいたと言われる伝説の場所です\nその探索も千代目ちゃんの任務なんだからね\n寄り道ばっかりしてたら千代目ちゃんに迷惑よ\nそうであったすまんすまん\nそれは相当アリアン殿長くて綺麗な足ですね\nお肌もスベスベで\nちょっと吉山ちゃんどこ触ってんの\nおかしい\nではここからは寄り道せずに行くとするか\nなポンタよ\nキューン\nああそうしたら畑に水を引くのにも困らねえだろ\nどうしたんでしょうか\nなんかこの村に入って