, \"confidence\": 0.9146}, {\"end\": 387.6, \"text\": \"premier\", \"start\": 387.16, \"confidence\": 0.8477}, {\"end\": 387.98, \"text\": \"degré,\", \"start\": 387.6, \"confidence\": 0.9929}, {\"end\": 388.1, \"text\": \"ma\", \"start\": 388.02, \"confidence\": 0.9697}, {\"end\": 388.34, \"text\": \"peur\", \"start\": 388.1, \"confidence\": 0.9956}, {\"end\": 388.5, \"text\": \"avec\", \"start\": 388.34, \"confidence\": 0.9619}, {\"end\": 388.8, \"text\": \"Joseph\", \"start\": 388.5, \"confidence\": 0.9561}, {\"end\": 388.98, \"text\": \"qui\", \"start\": 388.8, \"confidence\": 0.9463}, {\"end\": 389.32, \"text\": \"conduit,\", \"start\": 388.98, \"confidence\": 0.9915}, {\"end\": 389.42, \"text\": \"c\", \"start\": 389.34, \"confidence\": 0.9971}, {\"end\": 389.48, \"text\": \"\'est\", \"start\": 389.42, \"confidence\": 1}, {\"end\": 389.56, \"text\": \"qu\", \"start\": 389.48, \"confidence\": 0.9961}, {\"end\": 389.6, \"text\": \"\'il\", \"start\": 389.56, \"confidence\": 0.9919}, {\"end\": 389.76, \"text\": \"loupe\", \"start\": 389.6, \"confidence\": 0.9978}, {\"end\": 389.88, \"text\": \"les\", \"start\": 389.76, \"confidence\": 0.9878}, {\"end\": 390.14, \"text\": \"poteaux.\", \"start\": 389.88, \"confidence\": 0.992}], \"confidence\": 0.8505}, {\"end\": 393, \"text\": \"Enfin, non, moi, c\'est qu\'il loupe pas le poteau, c\'est justement qu\'il le prenne.\", \"start\": 390.28, \"words\": [{\"end\": 390.48, \"text\": \"Enfin,\", \"start\": 390.28, \"confidence\": 0.8145}, {\"end\": 390.72, \"text\": \"non,\", \"start\": 390.5, \"confidence\": 0.9805}, {\"end\": 390.88, \"text\": \"moi,\", \"start\": 390.76, \"confidence\": 0.9658}, {\"end\": 391.04, \"text\": \"c\", \"start\": 390.96, \"confidence\": 0.999}, {\"end\": 391.12, \"text\": \"\'est\", \"start\": 391.04, \"confidence\": 1}, {\"end\": 391.2, \"text\": \"qu\", \"start\": 391.12, \"confidence\": 0.9985}, {\"end\": 391.22, \"text\": \"\'il\", \"start\": 391.2, \"confidence\": 0.9597}, {\"end\": 391.