t\", \"start\": 462.34, \"confidence\": 0.8037}, {\"end\": 462.58, \"text\": \"à\", \"start\": 462.46, \"confidence\": 0.9907}, {\"end\": 462.82, \"text\": \"25\", \"start\": 462.58, \"confidence\": 0.9355}, {\"end\": 463.26, \"text\": \"rouleaux,\", \"start\": 462.82, \"confidence\": 0.9945}, {\"end\": 463.36, \"text\": \"il\", \"start\": 463.3, \"confidence\": 0.9551}, {\"end\": 463.44, \"text\": \"s\", \"start\": 463.36, \"confidence\": 0.6396}, {\"end\": 463.52, \"text\": \"\'est\", \"start\": 463.44, \"confidence\": 0.9978}, {\"end\": 463.66, \"text\": \"rien\", \"start\": 463.52, \"confidence\": 0.9893}, {\"end\": 464.08, \"text\": \"passé\", \"start\": 463.66, \"confidence\": 0.9883}, {\"end\": 464.38, \"text\": \"!\", \"start\": 464.08, \"confidence\": 0.5195}], \"confidence\": 0.8116}, {\"end\": 466.12, \"text\": \"Le pare-brise n\'est pas de cet accord, mais...\", \"start\": 464.38, \"words\": [{\"end\": 464.5, \"text\": \"Le\", \"start\": 464.38, \"confidence\": 0.8013}, {\"end\": 464.68, \"text\": \"pare\", \"start\": 464.5, \"confidence\": 0.9932}, {\"end\": 464.9, \"text\": \"-brise\", \"start\": 464.68, \"confidence\": 0.9943}, {\"end\": 465.04, \"text\": \"n\", \"start\": 464.9, \"confidence\": 0.6245}, {\"end\": 465.16, \"text\": \"pas\", \"start\": 465.04, \"confidence\": 0.9971}, {\"end\": 465.24, \"text\": \"de\", \"start\": 465.16, \"confidence\": 0.9941}, {\"end\": 465.34, \"text\": \"cet\", \"start\": 465.24, \"confidence\": 0.9741}, {\"end\": 465.56, \"text\": \"accord,\", \"start\": 465.34, \"confidence\": 0.9971}, {\"end\": 466.12, \"text\": \"mais...\", \"start\": 465.74, \"confidence\": 0.9395}], \"confidence\": 0.8116}, {\"end\": 466.86, \"text\": \"Bah ça va...\", \"start\": 466.12, \"words\": [{\"end\": 466.34, \"text\": \"Bah\", \"start\": 466.12, \"confidence\": 0.2245}, {\"end\": 466.52, \"text\": \"ça\", \"start\": 466.34, \"confidence\": 0.8252}, {\"end\": 466.86, \"text\": \"va...\", \"start\": 466.52, \"confidence\": 0.7603}], \