t\": 622.87, \"words\": [{\"end\": 623.09, \"text\": \"Et\", \"start\": 622.87, \"confidence\": 0.9839}, {\"end\": 623.27, \"text\": \"tu\", \"start\": 623.09, \"confidence\": 0.9858}, {\"end\": 623.61, \"text\": \"sauras\", \"start\": 623.27, \"confidence\": 0.8}, {\"end\": 624.03, \"text\": \"pourquoi\", \"start\": 623.61, \"confidence\": 0.9961}, {\"end\": 624.37, \"text\": \"!\", \"start\": 624.03, \"confidence\": 0.8779}], \"confidence\": 0.8084}, {\"end\": 626.03, \"text\": \"Ton nom est l\'éternel !\", \"start\": 624.37, \"words\": [{\"end\": 624.85, \"text\": \"Ton\", \"start\": 624.37, \"confidence\": 0.5669}, {\"end\": 625.09, \"text\": \"nom\", \"start\": 624.85, \"confidence\": 0.9937}, {\"end\": 625.23, \"text\": \"est\", \"start\": 625.09, \"confidence\": 0.9692}, {\"end\": 625.25, \"text\": \"l\", \"start\": 625.23, \"confidence\": 0.9912}, {\"end\": 625.77, \"text\": \"\'éternel\", \"start\": 625.25, \"confidence\": 0.9845}, {\"end\": 626.03, \"text\": \"!\", \"start\": 625.77, \"confidence\": 0.9995}], \"confidence\": 0.8084}, {\"end\": 634, \"text\": \"Ça freine un peu !\", \"start\": 631.8, \"words\": [{\"end\": 632.12, \"text\": \"Ça\", \"start\": 631.8, \"confidence\": 0.8423}, {\"end\": 633.6, \"text\": \"freine\", \"start\": 633.28, \"confidence\": 0.9248}, {\"end\": 633.68, \"text\": \"un\", \"start\": 633.6, \"confidence\": 0.9956}, {\"end\": 633.74, \"text\": \"peu\", \"start\": 633.68, \"confidence\": 0.9995}, {\"end\": 634, \"text\": \"!\", \"start\": 633.74, \"confidence\": 0.9932}], \"confidence\": 0.8084}, {\"end\": 636.62, \"text\": \"Bon, pourtant, je trouve que c\'est la peur qui a plus freiné la voiture.\", \"start\": 634, \"words\": [{\"end\": 634.32, \"text\": \"Bon,\", \"start\": 634, \"confidence\": 0.9805}, {\"end\": 634.56, \"text\": \"pourtant,\", \"start\": 634.32, \"confidence\": 0.2666}, {\"end\": 634.86, \"text\": \"je\", \"start\": 634.74, \"confidence\": 0.999}, {\"end\": 634.92, \"text\": \"trouve\", \"start\": 634.86, \"confidence\": 0.9956}, {\"end\": 635.1, \"text\": \"que\", \"start\": 634.92, \"confidence\": 1}, {\"end\": 635.18, \"text\": \"c\", \"start\": 635.1, \"confidence\": 1}, {\"end\": 635.26, \"text\": \"\'est\", \"start\": 635.18, \"confidence\": 1}, {\"end\": 635.3, \"text\": \"la\", \"start\": 635.26, \"confidence\": 1}, {\"end\": 635.58, \"text\": \"peur\", \"start\": 635.3, \"confidence\": 1}, {\"end\": 635.8, \"text\": \"qui\", \"start\": 635.58, \"confidence\": 1}, {\"end\": 635.86, \"text\": \"a\", \"start\": 635.8, \"confidence\": 1}, {\"end\": 635.98, \"text\": \"plus\", \"start\": 635.86, \"confidence\": 0.7295}, {\"end\": 636.3, \"text\": \"freiné\", \"start\": 635.98, \"confidence\": 0.9987}, {\"end\": 636.4, \"text\": \"la\", \"start\": 636.3, \"confidence\": 1}, {\"end\": 636.62, \"text\": \"voiture.\", \"start\": 636.4, \"confidence\": 1}], \"confidence\": 0.8084}, {\"end\": 639.4, \"text\": \"Alors, il y a... Oh, il y a des trucs qui ont bougé dans la voiture !\", \"start\": 636.9, \"words\": [{\"end\": 637.04, \"text\": \"Alors,\", \"start\": 636.9, \"confidence\": 0.7451}, {\"end\": 637.2, \"text\": \"il\", \"start\": 637.08, \"confidence\": 0.8984}, {\"end\": 637.22, \"text\": \"y\", \"start\": 637.2, \"confidence\": 1}, {\"end\": 637.3, \"text\": \"a...\", \"start\": 637.22, \"confidence\": 0.9731}, {\"end\": 637.96, \"text\": \"Oh,\", \"start\": 637.3, \"confidence\": 0.8467}, {\"end\": 638.18, \"text\": \"il\", \"start\": 637.98, \"confidence\": 0.998}, {\"end\": 638.2, \"text\": \"y\", \"start\": 638.18, \"confidence\": 1}, {\"end\": 638.24, \"text\": \"a\", \"start\": 638.2, \"confidence\": 1}, {\"end\": 638.3, \"text\": \"des\", \"start\": 638.24, \"confidence\": 1}, {\"end\": 638.5, \"text\": \"trucs\", \"start\": 638.3, \"confidence\": 1}, {\"end\": 638.6, \"text\": \"qui\", \"start\": 638.5, \"confidence\": 1}, {\"end\": 638.64, \"text\": \"ont\", \"start\": 638.6, \"confidence\": 1}, {\"end\": 638.86, \"text\": \"bougé\", \"start\": 63