71}, {\"end\": 679.56, \"text\": \"que\", \"start\": 679.4, \"confidence\": 0.999}, {\"end\": 679.72, \"text\": \"ça\", \"start\": 679.56, \"confidence\": 0.9995}, {\"end\": 679.9, \"text\": \"par\", \"start\": 679.72, \"confidence\": 0.9131}, {\"end\": 680.12, \"text\": \"rapport\", \"start\": 679.9, \"confidence\": 0.9995}, {\"end\": 680.2, \"text\": \"aux\", \"start\": 680.12, \"confidence\": 0.4258}, {\"end\": 680.48, \"text\": \"dégâts.\", \"start\": 680.2, \"confidence\": 0.9988}], \"confidence\": 0.8854}, {\"end\": 681.94, \"text\": \"Ça n\'a pas secoué tant que ça par rapport à ce que la voiture a pris.\", \"start\": 680.56, \"words\": [{\"end\": 680.6, \"text\": \"Ça\", \"start\": 680.56, \"confidence\": 0.8823}, {\"end\": 680.66, \"text\": \"ça\", \"start\": 680.6, \"confidence\": 1}, {\"end\": 680.82, \"text\": \"par\", \"start\": 680.66, \"confidence\": 0.9995}, {\"end\": 681.04, \"text\": \"rapport\", \"start\": 680.82, \"confidence\": 1}, {\"end\": 681.14, \"text\": \"à\", \"start\": 681.04, \"confidence\": 1}, {\"end\": 681.22, \"text\": \"ce\", \"start\": 681.14, \"confidence\": 1}, {\"end\": 681.3, \"text\": \"que\", \"start\": 681.22, \"confidence\": 1}, {\"end\": 681.4, \"text\": \"la\", \"start\": 681.3, \"confidence\": 1}, {\"end\": 681.62, \"text\": \"voiture\", \"start\": 681.4, \"confidence\": 1}, {\"end\": 681.78, \"text\": \"a\", \"start\": 681.62, \"confidence\": 1}, {\"end\": 681.94, \"text\": \"pris.\", \"start\": 681.78, \"confidence\": 1}], \"confidence\": 0.8854}, {\"end\": 683.72, \"text\": \"Parce que c\'est la voiture qui a encaissé.\", \"start\": 682.02, \"words\": [{\"end\": 682.16, \"text\": \"Parce\", \"start\": 682.02, \"confidence\": 0.9854}, {\"end\": 682.26, \"text\": \"que\", \"start\": 682.16, \"confidence\": 1}, {\"end\": 682.34, \"text\": \"c\", \"start\": 682.26, \"confidence\": 1}, {\"end\": 682.42, \"text\": \"\'est\", \"start\": 682.34, \"confidence\": 1}, {\"end\": 682.5, \"text\": \"la\", \"start\": 682.42, \"conf