"Des\", \"start\": 776.21, \"confidence\": 0.9785}, {\"end\": 776.75, \"text\": \"légers\", \"start\": 776.37, \"confidence\": 0.9915}, {\"end\": 777.01, \"text\": \"supports.\", \"start\": 776.75, \"confidence\": 0.9995}], \"confidence\": 0.8013}, {\"end\": 777.63, \"text\": \"Bon, faut rien.\", \"start\": 777.27, \"words\": [{\"end\": 777.41, \"text\": \"Bon,\", \"start\": 777.27, \"confidence\": 0.7437}, {\"end\": 777.51, \"text\": \"faut\", \"start\": 777.43, \"confidence\": 0.9473}, {\"end\": 777.63, \"text\": \"rien.\", \"start\": 777.51, \"confidence\": 0.998}], \"confidence\": 0.8013}, {\"end\": 781.45, \"text\": \"J\'ai une petite question, si on finit à l\'hôpital, on leur explique comment c\'est arrivé l\'accident ?\", \"start\": 777.63, \"words\": [{\"end\": 777.87, \"text\": \"J\", \"start\": 777.63, \"confidence\": 0.8198}, {\"end\": 777.95, \"text\": \"\'ai\", \"start\": 777.87, \"confidence\": 0.9988}, {\"end\": 777.97, \"text\": \"une\", \"start\": 777.95, \"confidence\": 0.9966}, {\"end\": 778.09, \"text\": \"petite\", \"start\": 777.97, \"confidence\": 0.9717}, {\"end\": 778.45, \"text\": \"question,\", \"start\": 778.09, \"confidence\": 0.9971}, {\"end\": 778.73, \"text\": \"si\", \"start\": 778.61, \"confidence\": 0.9868}, {\"end\": 778.87, \"text\": \"on\", \"start\": 778.73, \"confidence\": 0.9961}, {\"end\": 779.09, \"text\": \"finit\", \"start\": 778.87, \"confidence\": 0.9893}, {\"end\": 779.17, \"text\": \"à\", \"start\": 779.09, \"confidence\": 0.9897}, {\"end\": 779.51, \"text\": \"\'hôpital,\", \"start\": 779.17, \"confidence\": 0.9984}, {\"end\": 779.67, \"text\": \"on\", \"start\": 779.57, \"confidence\": 0.9941}, {\"end\": 779.75, \"text\": \"leur\", \"start\": 779.67, \"confidence\": 0.998}, {\"end\": 780.09, \"text\": \"explique\", \"start\": 779.75, \"confidence\": 0.9985}, {\"end\": 780.37, \"text\": \"comment\", \"start\": 780.09, \"confidence\": 0.9946}, {\"end\": 780.63, \"text\": \"c\", \"start\": 780.37, \"confidence\": 0.3584}, {\"end\": 780.67, \"text\": \"\'est\", \"start\": 780.63, \"confidence\": 0.9998}, {\"end\": 780.81, \"text\": \"arrivé\", \"start\": 780.67, \"confidence\": 0.9917}, {\"end\": 781.03, \"text\": \"l\", \"start\": 780.81, \"confidence\": 0.8921}, {\"end\": 781.29, \"text\": \"\'accident\", \"start\": 781.03, \"confidence\": 0.9997}, {\"end\": 781.45, \"text\": \"?\", \"start\": 781.29, \"confidence\": 0.7583}], \"confidence\": 0.8968}, {\"end\": 786.24, \"text\": \"Tu feras quand même attention parce qu\'on voit vachement moins bien les poteaux maintenant avec tout le scotch.\", \"start\": 782.3, \"words\": [{\"end\": 782.58, \"text\": \"Tu\", \"start\": 782.3, \"confidence\": 0.9629}, {\"end\": 783.14, \"text\": \"feras\", \"start\": 782.98, \"confidence\": 0.9932}, {\"end\": 783.28, \"text\": \"quand\", \"start\": 783.14, \"confidence\": 0.9888}, {\"end\": 783.4, \"text\": \"même\", \"start\": 783.28, \"confidence\": 0.9941}, {\"end\": 783.64, \"text\": \"attention\", \"start\": 783.4, \"confidence\": 0.9976}, {\"end\": 783.92, \"text\": \"parce\", \"start\": 783.64, \"confidence\": 0.6763}, {\"end\": 783.96, \"text\": \"qu\", \"start\": 783.92, \"confidence\": 0.937}, {\"end\": 784.04, \"text\": \"\'on\", \"start\": 783.96, \"confidence\": 0.9998}, {\"end\": 784.2, \"text\": \"voit\", \"start\": 784.04, \"confidence\": 0.9971}, {\"end\": 784.68, \"text\": \"vachement\", \"start\": 784.2, \"confidence\": 0.9927}, {\"end\": 784.9, \"text\": \"moins\", \"start\": 784.68, \"confidence\": 0.9995}, {\"end\": 785.06, \"text\": \"bien\", \"start\": 784.9, \"confidence\": 0.9995}, {\"end\": 785.18, \"text\": \"les\", \"start\": 785.06, \"confidence\": 0.998}, {\"end\": 785.48, \"text\": \"poteaux\", \"start\": 785.18, \"confidence\": 0.9985}, {\"end\": 785.64, \"text\": \"maintenant\", \"start\": 785.48, \"confidence\": 0.9272}, {\"end\": 785.84, \"text\": \"avec\", \"start\": 785.64, \"confidence\": 0.98}, {\"end\": 785.98, \"text\": \"tout\", \"start\": 785.84, \"co