": 944, \"confidence\": 0.9989}, {\"end\": 944.8, \"text\": \"ne\", \"start\": 944.7, \"confidence\": 0.9995}, {\"end\": 945.2, \"text\": \"suffisent\", \"start\": 944.8, \"confidence\": 0.999}, {\"end\": 945.34, \"text\": \"pas\", \"start\": 945.2, \"confidence\": 1}, {\"end\": 945.42, \"text\": \"à\", \"start\": 945.34, \"confidence\": 0.999}, {\"end\": 945.66, \"text\": \"arrêter\", \"start\": 945.42, \"confidence\": 1}, {\"end\": 945.72, \"text\": \"une\", \"start\": 945.66, \"confidence\": 1}, {\"end\": 945.92, \"text\": \"voiture.\", \"start\": 945.72, \"confidence\": 1}], \"confidence\": 0.8998}, {\"end\": 946.58, \"text\": \"Et en faut plus.\", \"start\": 946.14, \"words\": [{\"end\": 946.24, \"text\": \"Et\", \"start\": 946.14, \"confidence\": 0.9497}, {\"end\": 946.26, \"text\": \"en\", \"start\": 946.24, \"confidence\": 0.4341}, {\"end\": 946.42, \"text\": \"faut\", \"start\": 946.26, \"confidence\": 0.9922}, {\"end\": 946.58, \"text\": \"plus.\", \"start\": 946.42, \"confidence\": 1}], \"confidence\": 0.8998}, {\"end\": 947.44, \"text\": \"500 !\", \"start\": 946.84, \"words\": [{\"end\": 947.16, \"text\": \"500\", \"start\": 946.84, \"confidence\": 0.9907}, {\"end\": 947.44, \"text\": \"!\", \"start\": 947.16, \"confidence\": 0.814}], \"confidence\": 0.8998}, {\"end\": 955.17, \"text\": \"Ça, messieurs, ça s\'appelle une connerie.\", \"start\": 947.44, \"words\": [{\"end\": 947.88, \"text\": \"Ça,\", \"start\": 947.44, \"confidence\": 0.9624}, {\"end\": 954.19, \"text\": \"messieurs,\", \"start\": 953.89, \"confidence\": 0.999}, {\"end\": 954.31, \"text\": \"ça\", \"start\": 954.25, \"confidence\": 1}, {\"end\": 954.41, \"text\": \"s\", \"start\": 954.31, \"confidence\": 1}, {\"end\": 954.59, \"text\": \"\'appelle\", \"start\": 954.41, \"confidence\": 1}, {\"end\": 954.75, \"text\": \"une\", \"start\": 954.59, \"confidence\": 1}, {\"end\": 955.17, \"text\": \"connerie.\", \"start\": 954.75, \"confidence\": 0.9998}], \"confidence\": 0.8998}, {\"end\": 95