 1}, {\"end\": 238.57, \"text\": \"\'est\", \"start\": 238.53, \"confidence\": 1}, {\"end\": 238.61, \"text\": \"le\", \"start\": 238.57, \"confidence\": 1}, {\"end\": 238.95, \"text\": \"concept,\", \"start\": 238.61, \"confidence\": 1}, {\"end\": 239.21, \"text\": \"hein.\", \"start\": 239.11, \"confidence\": 0.9995}], \"confidence\": 0.8276}, {\"end\": 241.76, \"text\": \"Tu vois, regarde, si je jette ça, bah, ça l\'a arrêté, quoi.\", \"start\": 239.25, \"words\": [{\"end\": 239.37, \"text\": \"Tu\", \"start\": 239.25, \"confidence\": 0.7632}, {\"end\": 239.39, \"text\": \"vois,\", \"start\": 239.37, \"confidence\": 0.9932}, {\"end\": 239.61, \"text\": \"regarde,\", \"start\": 239.43, \"confidence\": 0.9878}, {\"end\": 239.73, \"text\": \"si\", \"start\": 239.63, \"confidence\": 0.9541}, {\"end\": 239.79, \"text\": \"je\", \"start\": 239.73, \"confidence\": 0.9902}, {\"end\": 239.97, \"text\": \"jette\", \"start\": 239.79, \"confidence\": 0.9983}, {\"end\": 240.11, \"text\": \"ça,\", \"start\": 239.97, \"confidence\": 1}, {\"end\": 240.81, \"text\": \"bah,\", \"start\": 240.25, \"confidence\": 0.6865}, {\"end\": 241.18, \"text\": \"ça\", \"start\": 241.08, \"confidence\": 0.999}, {\"end\": 241.3, \"text\": \"l\", \"start\": 241.18, \"confidence\": 0.6313}, {\"end\": 241.34, \"text\": \"\'a\", \"start\": 241.3, \"confidence\": 0.9949}, {\"end\": 241.6, \"text\": \"arrêté,\", \"start\": 241.34, \"confidence\": 0.9992}, {\"end\": 241.76, \"text\": \"quoi.\", \"start\": 241.66, \"confidence\": 1}], \"confidence\": 0.8276}, {\"end\": 243.02, \"text\": \"On peut jeter un Sylvain pour voir ?\", \"start\": 241.76, \"words\": [{\"end\": 242, \"text\": \"On\", \"start\": 241.76, \"confidence\": 0.5986}, {\"end\": 242.12, \"text\": \"peut\", \"start\": 242, \"confidence\": 0.9849}, {\"end\": 242.32, \"text\": \"jeter\", \"start\": 242.12, \"confidence\": 0.9856}, {\"end\": 242.42, \"text\": \"un\", \"start\": 242.32, \"confidence\": 0.9932}, {\"end\": 242.7, \"text\": \"Syl